'use strict';
const $=s=>document.querySelector(s);
const game=$('#game'),card=$('#card'),overlay=$('#overlay'),hud=$('#hud');
const definitions=[['lamp','Lámpara','lamp.png','¡Luz!'],['phone','Celular','phone.png','¡Ring!'],['tv','Televisión','tv.png','¡Ruido!'],['speaker','Bocina','speaker.png','¡Música!'],['window','Ventana',null,'¡Luz exterior!'],['mover','Nota musical',null,'¡Detén la nota!']];
const objects=definitions.map(([id,name,file,label],index)=>{const el=document.createElement('button');el.className=`object ${id}`;el.setAttribute('aria-label',`${name}: apagado. Tecla ${index+1}`);el.innerHTML=(file?`<img src="assets/${file}" alt="">`:id==='mover'?'♪':'')+`<span class="signal">${label}</span>`;$('#objects').append(el);el.addEventListener('click',()=>disable(index));return {id,name,el,active:false,age:0};});
const tips=['Toca lo que haga ruido o emita luz para cuidar su descanso.','Dormir y despertar a la misma hora ayuda a tener una rutina.','Una habitación tranquila, fresca y oscura favorece el descanso.','Apaga las pantallas al menos 30 minutos antes de dormir.','Evita la cafeína por la tarde y por la noche.','Dormir bien también ayuda a tu memoria y concentración.'];
let state='intro',elapsed=0,rest=100,cleared=0,score=0,nextSpawn=1,last=0,frame=0,previousFirst=-1,firstSpawn=true;
const remaining=()=>`00:${String(Math.ceil(Math.max(0,30-elapsed))).padStart(2,'0')}`;
function intro(){state='intro';hud.hidden=true;overlay.hidden=false;card.className='card';card.innerHTML=`<h1 id="card-title">Una noche tranquila</h1><p><b>Taso está durmiendo.<br>¡Ayuda a cuidar su descanso!</b></p><h2>¿Cómo jugar?</h2><p class="instructions">Toca los objetos cuando hagan ruido o emitan luz. Apágalos antes de que despierten a Taso.</p><p class="instructions">Detén también la nota musical que se acerca a él. Mantén la habitación tranquila durante <b>30 segundos</b>.</p><p class="warning">¡Atención! Cada vez aparecerán más distracciones.</p><button class="primary" data-action="start">Comenzar</button><small>También puedes usar las teclas 1–6. Pulsa Esc para pausar.</small>`;objects.forEach(o=>{o.el.disabled=true;o.el.hidden=o.id==='mover';});}
function start(){cancelAnimationFrame(frame);state='playing';elapsed=0;rest=100;cleared=0;score=0;nextSpawn=1.5;firstSpawn=true;last=performance.now();game.classList.remove('won','lost','paused');$('#awake').hidden=true;$('.zzz').hidden=false;objects.forEach(o=>{o.active=false;o.age=0;o.el.classList.remove('active');o.el.disabled=true;o.el.hidden=o.id==='mover';});overlay.hidden=true;hud.hidden=false;draw();$('#pause').focus();frame=requestAnimationFrame(tick);}
function spawn(){const limit=elapsed<10?2:elapsed<23?3:4;if(objects.filter(o=>o.active).length>=limit)return;let available=objects.filter(o=>!o.active);if(firstSpawn&&available.length>1)available=available.filter(o=>objects.indexOf(o)!==previousFirst);if(!available.length)return;const o=available[Math.floor(Math.random()*available.length)];if(firstSpawn){previousFirst=objects.indexOf(o);firstSpawn=false;}o.active=true;o.age=0;o.el.hidden=false;o.el.disabled=false;o.el.classList.add('active');o.el.setAttribute('aria-label',`${o.name}: activo. Toca para apagar. Tecla ${objects.indexOf(o)+1}`);}
function disable(index){const o=objects[index];if(state!=='playing'||!o.active)return;o.active=false;o.el.classList.remove('active');o.el.disabled=true;o.el.setAttribute('aria-label',`${o.name}: apagado`);cleared++;score+=10+(o.age<1?5:0);draw();}
function advance(dt){if(state!=='playing')return;const active=objects.filter(o=>o.active);const availableTime=Math.min(dt,30-elapsed);const damageAt=t=>active.reduce((n,o)=>{const exposed=Math.max(0,o.age+t-.65)-Math.max(0,o.age-.65);const close=o.id==='mover'?Math.max(0,o.age+t-3)-Math.max(0,o.age-3):0;return n+exposed*3+close*3;},0);let step=availableTime;if(damageAt(step)>=rest){let low=0,high=step;for(let i=0;i<40;i++){const mid=(low+high)/2;if(damageAt(mid)<rest)low=mid;else high=mid;}step=high;}const damage=damageAt(step);elapsed+=step;rest=Math.max(0,rest-damage);active.forEach(o=>o.age+=step);if(rest<=.000001){rest=0;finish(false);return;}if(elapsed>=30){elapsed=30;finish(true);return;}nextSpawn-=step;if(nextSpawn<=0){spawn();if(elapsed>15&&Math.random()<.25)spawn();nextSpawn=Math.max(.85,2.2-elapsed*.045)*(.8+Math.random()*.4);}draw();}
function tick(now){if(state!=='playing')return;advance(Math.max(0,(now-last)/1000));last=now;if(state==='playing')frame=requestAnimationFrame(tick);}
function draw(){const progress=elapsed/30*100;$('#time-fill').style.width=`${progress}%`;$('#time-track').setAttribute('aria-valuenow',elapsed.toFixed(1));$('#clock').textContent=remaining();$('#rest-fill').style.height=`${rest}%`;$('#rest-track').style.setProperty('--rest',`${rest}%`);$('#rest-track').setAttribute('aria-valuenow',Math.round(rest));$('#rest-label').textContent=`${Math.ceil(rest)}%`;$('#count').textContent=`${cleared} apagadas`;$('#tip').textContent=tips[Math.min(5,Math.floor(elapsed/5))];const moving=objects[5];if(moving.active){const p=Math.min(1,moving.age/5);moving.el.style.left=`${77-p*47}%`;moving.el.style.top=`${40+p*24}%`;}}
function pause(){if(state!=='playing')return;advance(Math.max(0,(performance.now()-last)/1000));if(state!=='playing')return;state='paused';cancelAnimationFrame(frame);game.classList.add('paused');overlay.hidden=false;card.className='card';card.innerHTML=`<h1 id="card-title">¡Una pequeña pausa!</h1><p><b>El juego está en pausa.</b><br>Continúa cuando estés listo.</p><p>Tiempo restante</p><div class="pause-time">${remaining()}</div><div class="pause-actions"><button data-action="resume">Continuar</button><button data-action="start">Reiniciar</button></div>`;$('#room').inert=true;hud.inert=true;card.querySelector('button').focus();}
function resume(){if(state!=='paused')return;state='playing';$('#room').inert=false;hud.inert=false;game.classList.remove('paused');overlay.hidden=true;last=performance.now();$('#pause').focus();frame=requestAnimationFrame(tick);}
function finish(won){state=won?'won':'lost';cancelAnimationFrame(frame);draw();game.classList.add(state);$('#awake').hidden=won;$('.zzz').hidden=!won;objects.forEach(o=>{o.el.disabled=true;});hud.hidden=true;overlay.hidden=false;card.className='card result';const points=score+(won?100:0);const hours=(elapsed/30*9).toLocaleString('es-MX',{maximumFractionDigits:1});card.innerHTML=`<h1 id="card-title">${won?'¡Llegó el amanecer!':'¡Taso se despertó!'}</h1><p>${won?'Taso durmió toda la noche.<br><b>¡Cuidaste bien su descanso!</b>':'Apaga las distracciones más rápido para mantenerlo dormido hasta el amanecer.<br><b>¡Puedes volver a intentarlo!</b>'}</p><div class="points">${points} pts</div><div class="stats"><div class="stat">Horas<br>dormidas<strong>${hours} h</strong></div><div class="stat">Distracciones<br>apagadas<strong>${cleared}</strong></div></div><div class="actions"><button data-action="learn">¿Cuánto necesita dormir?</button><button data-action="start">Volver a jugar</button></div><small>Las horas representan el tiempo dentro del juego.<br>10 puntos por distracción, +5 por reaccionar en menos de 1 segundo y +100 al amanecer.</small>`;card.querySelector('button').focus();}
$('#pause').addEventListener('click',pause);
document.addEventListener('click',e=>{const action=e.target.closest('[data-action]')?.dataset.action;if(action==='start'){$('#room').inert=false;hud.inert=false;start();}if(action==='resume')resume();if(action==='learn'){if(state==='playing')pause();$('#learn').showModal();}});
document.addEventListener('keydown',e=>{if($('#learn').open)return;if(e.key==='Escape'){if(state==='playing')pause();else if(state==='paused')resume();}if(/^[1-6]$/.test(e.key)&&state==='playing')disable(Number(e.key)-1);if(state==='paused'&&e.key==='Tab'){const buttons=card.querySelectorAll('button');if(e.shiftKey&&document.activeElement===buttons[0]){e.preventDefault();buttons[1].focus();}else if(!e.shiftKey&&document.activeElement===buttons[1]){e.preventDefault();buttons[0].focus();}}});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&state==='playing')pause();});
intro();
